export const mdastToText = (node) => {
    if (typeof node.value === 'string')
        return node.value;
    if (!node.children)
        return '';
    return node.children.map(mdastToText).join('');
};
export const hastToText = (node) => {
    if (node.type === 'text')
        return node.value;
    if (node.type === 'element')
        return node.children.map(hastToText).join('');
    return '';
};
